std::string multipart(const std::vector<DiscoveryWorkbenchPart>& parts){std::string body;for(const auto& part:parts){body+="--Owned75\r\nContent-Disposition: form-data; name=\""+part.name+"\"";if(part.file)body+="; filename=\""+part.filename+"\"";body+="\r\nContent-Type: application/octet-stream\r\n\r\n"+part.bytes+"\r\n";}return body+"--Owned75--\r\n";}
